"""Tenant administration workspace for product connections and integration health."""
from fastapi import APIRouter, Response
from fastapi.responses import HTMLResponse

router = APIRouter(tags=["CRM security and integrations workspace"], include_in_schema=False)
_HEADERS = {"Cache-Control":"no-store","Content-Security-Policy":"default-src 'self'; script-src 'self'; style-src 'unsafe-inline'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'","Referrer-Policy":"no-referrer","X-Content-Type-Options":"nosniff"}
_PAGE = """<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>مدیریت، امنیت و اتصال | فانل CRM</title><style>
:root{font-family:Tahoma,Arial,sans-serif;color:#172c42;background:#f4f7fb}*{box-sizing:border-box}body{margin:0}.app{min-height:100vh;display:grid;grid-template-columns:230px 1fr}aside{background:#fff;border-left:1px solid #e3e9f0;padding:20px 14px;position:sticky;top:0;height:100vh}.brand{font-size:19px;font-weight:bold;padding:0 10px 24px}.brand b{color:#158b91}nav{display:grid;gap:5px}.nav{display:block;padding:11px;border-radius:9px;color:#54677a;text-decoration:none;font-size:12px}.nav.active{background:#eaf4f7;color:#125779}.main{min-width:0;padding:24px clamp(16px,3vw,42px) 48px}h1{font-size:25px;margin:0 0 8px}.sub{color:#718092;font-size:13px;line-height:1.8;margin:0 0 16px}.status{min-height:20px;color:#718092;font-size:12px}.error{color:#a74137}.notice{background:#eef6f8;border:1px solid #d8e9ed;border-right:3px solid #19838d;padding:12px 15px;border-radius:10px;color:#3f6672;font-size:11px;line-height:1.9;margin:14px 0}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:11px;margin:14px 0}.card{background:#fff;border:1px solid #e5eaf0;border-radius:12px;padding:16px;box-shadow:0 4px 14px #1c334408;min-width:0}.label{color:#657487;font-size:11px}.value{font-size:22px;font-weight:bold;color:#1a334c;margin:9px 0 3px}.meta{font-size:10px;color:#8290a0;line-height:1.7}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.wide{grid-column:1/-1}.heading{display:flex;justify-content:space-between;align-items:center;gap:10px;margin:0 0 12px}.heading h2{font-size:15px;margin:0}.list{display:grid;gap:8px}.item{border:1px solid #e8edf2;border-radius:9px;padding:12px;font-size:11px;line-height:1.8}.item strong{display:block;color:#304b60;font-size:12px}.tags{display:flex;gap:5px;flex-wrap:wrap;margin-top:7px}.pill{display:inline-block;border-radius:99px;background:#eff4f7;color:#506879;padding:3px 8px;font-size:10px}.good{background:#eaf6f1;color:#24745b}.bad{background:#fff0ed;color:#a3493e}.warn{background:#fff7e8;color:#8a641d}.actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:9px}button{font:inherit;cursor:pointer;border-radius:8px;padding:8px 11px;font-size:10px}.primary{border:0;background:#126b91;color:#fff}.danger{border:1px solid #f0d4d1;background:#fff7f6;color:#a74137}.secondary{border:1px solid #d8e2ea;background:#fff;color:#31536c}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;min-width:520px;font-size:11px}th,td{text-align:right;padding:9px 7px;border-bottom:1px solid #eef1f4}th{background:#f8fafc;color:#728092}td{color:#33465c}.empty{font-size:11px;line-height:1.8;color:#7b8998;text-align:center;padding:14px;border:1px dashed #d4dde6;border-radius:9px}.secret{display:none;margin-top:10px;padding:12px;border:1px solid #f2dfb8;background:#fff9ec;border-radius:9px;font-size:11px;line-height:1.8;overflow-wrap:anywhere}.secret code{display:block;direction:ltr;text-align:left;font-family:monospace;background:#fff;padding:8px;border-radius:6px;margin:8px 0}.foot{color:#8995a1;font-size:10px;line-height:1.8;margin-top:13px}@media(max-width:900px){.grid{grid-template-columns:1fr}.wide{grid-column:auto}}@media(max-width:760px){.app{display:block}aside{position:relative;height:auto;border:0;border-bottom:1px solid #e3e9f0;padding:12px}.brand{padding-bottom:8px}nav{display:flex;overflow:auto}.nav{white-space:nowrap}.kpis{grid-template-columns:repeat(2,1fr)}}@media(max-width:480px){.main{padding:15px 12px}.kpis{gap:7px}.card{padding:12px}.value{font-size:18px}}</style><script src="/assets/crm-security-integrations.js" defer></script></head><body><div class="app"><aside><div class="brand">فانل <b>CRM</b></div><nav aria-label="ماژول‌های CRM"><a class="nav" href="/workspace/marketing-manager">میزکار مدیر بازاریابی</a><a class="nav" href="/workspace/crm-local-marketing">شعب و بازاریابی محلی</a><a class="nav" href="/workspace/crm-brand-reputation">برند و اعتبار بازار</a><a class="nav active" href="/workspace/crm-security-integrations" aria-current="page">مدیریت، امنیت و اتصال</a><a class="nav" href="/workspace/crm-analytics">تحلیل و هوش تجاری</a></nav></aside><main class="main"><h1>مدیریت، امنیت و اتصال</h1><p class="sub">اتصال محصولات فانل و مشتریان سازمانی به CRM، پایش سلامت تبادل داده و ادارهٔ امن اعتبارنامه‌ها.</p><div class="notice">اعتبارنامهٔ محصول فقط هنگام ایجاد یا چرخش نمایش داده می‌شود. آن را همان لحظه در مخزن امن مقصد ذخیره کنید؛ صفحه آن را نگه نمی‌دارد.</div><p id="status" class="status" role="status" aria-live="polite"></p><section class="kpis"><article class="card"><div class="label">اتصال‌های ثبت‌شده</div><div id="connection-count" class="value">—</div><div class="meta">شامل اتصال‌های لغوشده</div></article><article class="card"><div class="label">رویدادهای ناموفق</div><div id="failed-count" class="value">—</div><div class="meta">نیازمند بررسی یا ارسال مجدد</div></article><article class="card"><div class="label">رویدادهای پردازش‌شده</div><div id="processed-count" class="value">—</div><div class="meta">در صف ورودی یکپارچه‌سازی</div></article><article class="card"><div class="label">تغییر رضایت در انتظار</div><div id="consent-pending" class="value">—</div><div class="meta">صف همگام‌سازی محصولات</div></article></section><div class="grid"><section class="card wide"><div class="heading"><h2>اتصال محصولات</h2><button id="refresh" class="secondary" type="button">به‌روزرسانی</button></div><div id="connections" class="list"><div class="empty">در حال دریافت اتصال‌ها…</div></div><div id="secret" class="secret" role="status" aria-live="polite"></div></section><section class="card"><div class="heading"><h2>سلامت صف رویدادها</h2></div><div id="queue-health" class="table-wrap"><div class="empty">در حال دریافت…</div></div></section><section class="card"><div class="heading"><h2>همگام‌سازی تغییرات رضایت</h2></div><div id="consent-health" class="list"><div class="empty">در حال دریافت…</div></div></section><section class="card wide"><div class="heading"><h2>رویدادهای ناموفق</h2><span class="meta">محتوای دادهٔ رویداد در این فهرست نمایش داده نمی‌شود</span></div><div id="failed-events" class="list"><div class="empty">در حال دریافت…</div></div></section></div><p class="foot">مدیریت اتصال‌ها و عملیات صف فقط برای کاربر دارای مجوز مدیریتی یکپارچه‌سازی در فضای کاری فعال است. اقدام‌ها در سرور ممیزی می‌شوند.</p></main></div></body></html>"""
_SCRIPT = """(()=>{
const $=id=>document.getElementById(id),fmt=new Intl.NumberFormat("fa-IR");let connections=[],failures=[];
function say(s,e=false){$("status").textContent=s;$("status").classList.toggle("error",e)}function el(t,v,c=""){const n=document.createElement(t);n.textContent=String(v??"—");if(c)n.className=c;return n}
async function api(path,options={}){const h={Accept:"application/json",...(options.headers||{})};if(options.body)h["Content-Type"]="application/json";const r=await fetch(path,{...options,headers:h,credentials:"same-origin"});if(r.status===204)return null;let d={};try{d=await r.json()}catch(_){}if(!r.ok)throw Error(typeof d.detail==="string"?d.detail:"عملیات ناموفق بود");return d}
function button(label,cls,fn){const b=el("button",label,cls);b.type="button";b.addEventListener("click",fn);return b}
function displaySecret(label,value){const box=$("secret");box.replaceChildren(el("strong",label),el("div","این مقدار فقط اکنون نمایش داده می‌شود؛ آن را در محل امن ذخیره کنید."));const code=el("code",value);box.append(code);box.style.display="block";box.scrollIntoView({behavior:"smooth",block:"center"})}
async function refresh(){say("در حال دریافت اتصال‌ها و سلامت صف‌ها…");try{const results=await Promise.allSettled([api("/api/v1/integrations/connections"),api("/api/v1/integrations/connections/consent-sync"),api("/api/v1/integrations/events/health"),api("/api/v1/integrations/events/failed?limit=50")]);const [c,s,h,f]=results;connections=c.status==="fulfilled"?c.value:[];failures=f.status==="fulfilled"?f.value:[];$("connection-count").textContent=fmt.format(connections.length);$("failed-count").textContent=fmt.format(failures.length);$("processed-count").textContent=fmt.format(h.status==="fulfilled"?h.value.reduce((n,x)=>n+x.processed_count,0):0);$("consent-pending").textContent=fmt.format(s.status==="fulfilled"?s.value.pending_total:0);
drawConnections();drawHealth(h.status==="fulfilled"?h.value:[]);drawConsent(s.status==="fulfilled"?s.value.items:[]);drawFailures();const errors=results.filter(x=>x.status==="rejected").length;say(errors?"بعضی گزارش‌ها بارگیری نشدند؛ دسترسی یا وضعیت سرویس را بررسی کنید.":"اتصال‌ها و وضعیت تبادل داده به‌روز شد.",errors>0)}catch(e){say("اطلاعات بارگیری نشد: "+e.message,true)}}
function drawConnections(){const box=$("connections");box.replaceChildren();if(!connections.length){box.append(el("div","اتصال محصولی ثبت نشده است.","empty"));return}for(const c of connections){const item=document.createElement("article");item.className="item";item.append(el("strong",c.source_product));item.append(el("span",c.revoked_at?"لغوشده":"فعال", "pill "+(c.revoked_at?"bad":"good")));const tags=document.createElement("div");tags.className="tags";for(const e of c.allowed_event_types)tags.append(el("span",e,"pill"));for(const g of c.contract_grants)tags.append(el("span",g.contract_name+" · v"+g.contract_version,"pill"));item.append(tags);const actions=document.createElement("div");actions.className="actions";if(!c.revoked_at){actions.append(button("چرخش اعتبارنامه","secondary",async()=>{if(!confirm("اعتبارنامهٔ جدید صادر شود؟ مقصد باید بلافاصله به‌روزرسانی شود."))return;try{const d=await api("/api/v1/integrations/connections/"+encodeURIComponent(c.id)+"/rotate-credential",{method:"POST"});displaySecret("اعتبارنامهٔ جدید برای "+c.source_product,d.credential);say("اعتبارنامه چرخید؛ مقدار جدید را امن ذخیره و در محصول مقصد اعمال کنید.")}catch(e){say(e.message,true)}}));actions.append(button("لغو اتصال","danger",async()=>{if(!confirm("این اتصال محصول لغو شود؟ ارسال رویدادهای آن متوقف خواهد شد."))return;try{await api("/api/v1/integrations/connections/"+encodeURIComponent(c.id)+"/revoke",{method:"POST"});$("secret").style.display="none";say("اتصال لغو شد.");await refresh()}catch(e){say(e.message,true)}}))}item.append(actions);box.append(item)}}
function drawHealth(rows){const box=$("queue-health");if(!rows.length){box.replaceChildren(el("div","رویدادی در صف ثبت نشده است.","empty"));return}const table=document.createElement("table"),head=document.createElement("tr");["محصول","دریافتی","در حال پردازش","پردازش‌شده","ناموفق"].forEach(x=>head.append(el("th",x)));const th=document.createElement("thead");th.append(head);table.append(th);const body=document.createElement("tbody");for(const x of rows){const tr=document.createElement("tr");[x.source_product,x.received_count,x.processing_count,x.processed_count,x.failed_count].forEach(v=>tr.append(el("td",fmt.format(typeof v==="number"?v:v))));body.append(tr)}table.append(body);box.replaceChildren(table)}
function drawConsent(rows){const box=$("consent-health");box.replaceChildren();if(!rows.length){box.append(el("div","اتصال دارای قرارداد همگام‌سازی رضایت ثبت نشده است.","empty"));return}for(const x of rows){const item=document.createElement("article");item.className="item";item.append(el("strong",x.source_product));item.append(el("span",x.status==="behind"?"در انتظار همگام‌سازی":"همگام","pill "+(x.status==="behind"?"warn":"good")));item.append(el("div","تولیدشده: "+fmt.format(x.produced_sequence)+" · تأییدشده: "+fmt.format(x.acknowledged_sequence)+" · در انتظار: "+fmt.format(x.pending_count)));box.append(item)}}
function drawFailures(){const box=$("failed-events");box.replaceChildren();if(!failures.length){box.append(el("div","رویداد ناموفقی ثبت نشده است.","empty"));return}for(const x of failures){const item=document.createElement("article");item.className="item";item.append(el("strong",x.source_product+" · "+x.event_type));item.append(el("div",x.contract_name+" نسخهٔ "+fmt.format(x.contract_version)+" · تلاش: "+fmt.format(x.attempt_count)));item.append(el("span","کد خطا: "+(x.last_error_code||"نامشخص"),"pill bad"));item.append(button("ارسال مجدد","secondary",async()=>{if(!confirm("این رویداد برای پردازش مجدد به صف برگردد؟"))return;try{await api("/api/v1/integrations/events/"+encodeURIComponent(x.id)+"/retry",{method:"POST"});say("رویداد به صف بازگردانده شد.");await refresh()}catch(e){say(e.message,true)}}));box.append(item)}}
$("refresh").addEventListener("click",refresh);refresh();
})();"""
@router.get("/workspace/crm-security-integrations", response_class=HTMLResponse)
async def security_integrations_workspace() -> HTMLResponse:
    return HTMLResponse(_PAGE, headers=_HEADERS)

@router.get("/assets/crm-security-integrations.js")
async def security_integrations_script() -> Response:
    return Response(_SCRIPT, media_type="application/javascript", headers=_HEADERS)
